add_filter( 'gettext_woocommerce', 'perfectpixel_replace_woocommerce_strings', 20, 2 );

function perfectpixel_replace_woocommerce_strings( $translation, $text ) {
	static $map = null;
	if ( null === $map ) {
		$map = array();
		foreach ( explode( '|', '{{string_replacements}}' ) as $pair ) {
			$parts = explode( '=', $pair, 2 );
			if ( 2 === count( $parts ) && '' !== trim( $parts[0] ) ) {
				$map[ trim( $parts[0] ) ] = trim( $parts[1] );
			}
		}
	}
	return isset( $map[ $text ] ) ? $map[ $text ] : $translation;
}
